  // (Device battery, piece P1: Linux and macOS — the access card, the Mac note, the systems' own words.)
  batNote_noAccess: "Linux가 아직 Kurokawa Tools에 이 장치를 읽도록 허용하지 않습니다. 아래의 'Linux에서 읽기 허용'을 보세요",
  batAccessTitle: "Linux에서 읽기 허용",
  batAccessBody: "여기 있는 일부 장치는 raw HID 노드로만 읽을 수 있는데, Linux는 이를 사용자 계정에 닫아 둡니다. udev 규칙은 Kurokawa Tools가 읽을 수 있는 장치에서 배터리를 알려 주는 인터페이스만 열며, 키보드 입력이나 마우스 움직임은 열지 않습니다. Bluetooth에서는 게임 컨트롤러만 엽니다.",
  batAccessFile: "규칙이 여기에 저장되었습니다:",
  batAccessSteps: "터미널에서 다음 두 명령을 실행하세요(암호를 묻습니다):",
  batAccessAfter: "그다음 장치를 뽑았다가 다시 꽂고(또는 껐다 켜고) 새로 고치세요. Kurokawa Tools는 이 명령을 직접 실행하지 않습니다. 되돌리려면 /etc/udev/rules.d에서 파일을 삭제하세요.",
  batAccessNotSaved: "규칙 파일을 앱 폴더에 저장하지 못했습니다.",
  batMacTitle: "macOS에서는",
  batMacBody: "여기서는 macOS가 직접 알려 주는 잔량을 보여 줍니다: Apple 키보드·마우스·트랙패드, 이어폰 같은 블루투스 장치. 컨트롤러·마우스·키보드·헤드셋과 직접 통신하는 판독기는 아직 macOS에서 지원되지 않으며, 장치 연결은 시스템의 블루투스 설정에서 합니다.",
  batEmpty1_macos: "Apple 키보드·마우스·트랙패드, 그리고 드라이버가 macOS에 잔량을 알려 주는 장치.",
  batEmpty2_macos: "macOS가 잔량을 알려 주는 블루투스 장치(이어폰의 왼쪽·오른쪽·케이스 포함).",
  batEmpty3_macos: "컨트롤러, 그리고 제조사 고유 프로토콜로 읽는 마우스·키보드·헤드셋은 아직 macOS에서 읽지 않습니다.",
  batEmptyLater_macos: "이 판독은 새것이며 실제 Mac에서는 아직 시험하지 않아 일부 장치가 빠질 수 있습니다.",
  batSafeNote_macos: "장치는 읽기만 합니다. macOS가 직접 알려 주는 내용만 보여 주며 장치에는 아무것도 보내지 않습니다.",
  batEmpty2_linux: "BlueZ가 잔량을 보관하는 블루투스 장치, 그리고 Linux 커널이 직접 배터리를 읽는 장치(PlayStation, Nintendo, Logitech 등).",
